window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a134c34c7d19f43f"]={"versions": [{"id": "FIG-a134c34c7d19f43f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Spezifikation der Hardware-Ressourcen (AUTOSAR Resource Template ECU). Das Diagramm modelliert die strukturelle Anbindung und Schnittstellenverknüpfung von peripheren Hardware-Komponenten (<code>Peripheral</code>) an Prozessoren und ECU-Elektronik über Hardware-Ports im Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>HWElement</code></strong>: Allgemeine Hardware-Basisklasse, spezialisiert bzw. instanziiert durch:\n<ul class=\"fig-list\"><li><code>ProcessingUnit</code>: Repräsentiert die Recheneinheit/den Prozessorkern.\n</li><li><code>Peripheral</code>: Repräsentiert die periphere Hardware-Komponente.\n</li><li><code>ECUElectronics</code>: Repräsentiert die übergeordnete Steuergeräte-Elektronik.\n</li></ul>\n</li><li><strong><code>HWPort</code></strong>: Allgemeine Schnittstellen-Basisklasse für Hardware-Verbindungen, spezialisiert durch:\n<ul class=\"fig-list\"><li><code>MemoryMappedHWPort</code>: Speicherabgebildeter Port für den prozessornahen Zugriff.\n</li><li><code>PeripheralHWPort</code>: Hardware-Port zur peripheren Anbindung an die ECU-Elektronik.\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>ProcessingUnit</code> referenziert über eine gerichtete Abhängigkeit (gestrichelter Pfeil mit offener Pfeilspitze) den <code>MemoryMappedHWPort</code>.\n</li><li><code>Peripheral</code> referenziert über eine gerichtete Abhängigkeit nach links den <code>MemoryMappedHWPort</code>.\n</li><li><code>Peripheral</code> referenziert über eine gerichtete Abhängigkeit nach rechts den <code>PeripheralHWPort</code>.\n</li><li><code>ECUElectronics</code> referenziert über eine gerichtete Abhängigkeit von oben den <code>PeripheralHWPort</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die topologische Kopplung: Peripherieelemente koppeln prozessorintern über memory-mapped Hardware-Ports an die Recheneinheit und extern/steuergeräteseitig über Peripheral-Hardware-Ports an die Steuergeräteelektronik.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gilt als normative Metamodell-Definition für ECU-Hardware-Beschreibungen im AUTOSAR-Standard. Bei der Modellierung von ECU-Ressourcenbeschreibungen müssen Peripheriemodule über die beiden spezialisierten HWPort-Klassen angebunden werden: prozessorzugängliche Register-/Speicherschnittstellen sind als <code>MemoryMappedHWPort</code> zu typisieren, während Verbindungen zur ECU-Elektronik als <code>PeripheralHWPort</code> abzubilden sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ac9f9f220cf8234d", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Spezifikation der Hardware-Ressourcen (AUTOSAR Resource Template ECU). Das Diagramm modelliert die strukturelle Anbindung und Schnittstellenverknüpfung von peripheren Hardware-Komponenten (<code>Peripheral</code>) an Prozessoren und ECU-Elektronik über Hardware-Ports im Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>HWElement</code></strong>: Allgemeine Hardware-Basisklasse, spezialisiert bzw. instanziiert durch:\n<ul class=\"fig-list\"><li><code>ProcessingUnit</code>: Repräsentiert die Recheneinheit/den Prozessorkern.\n</li><li><code>Peripheral</code>: Repräsentiert die periphere Hardware-Komponente.\n</li><li><code>ECUElectronics</code>: Repräsentiert die übergeordnete Steuergeräte-Elektronik.\n</li></ul>\n</li><li><strong><code>HWPort</code></strong>: Allgemeine Schnittstellen-Basisklasse für Hardware-Verbindungen, spezialisiert durch:\n<ul class=\"fig-list\"><li><code>MemoryMappedHWPort</code>: Speicherabgebildeter Port für den prozessornahen Zugriff.\n</li><li><code>PeripheralHWPort</code>: Hardware-Port zur peripheren Anbindung an die ECU-Elektronik.\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>ProcessingUnit</code> referenziert über eine gerichtete Abhängigkeit (gestrichelter Pfeil mit offener Pfeilspitze) den <code>MemoryMappedHWPort</code>.\n</li><li><code>Peripheral</code> referenziert über eine gerichtete Abhängigkeit nach links den <code>MemoryMappedHWPort</code>.\n</li><li><code>Peripheral</code> referenziert über eine gerichtete Abhängigkeit nach rechts den <code>PeripheralHWPort</code>.\n</li><li><code>ECUElectronics</code> referenziert über eine gerichtete Abhängigkeit von oben den <code>PeripheralHWPort</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die topologische Kopplung: Peripherieelemente koppeln prozessorintern über memory-mapped Hardware-Ports an die Recheneinheit und extern/steuergeräteseitig über Peripheral-Hardware-Ports an die Steuergeräteelektronik.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gilt als normative Metamodell-Definition für ECU-Hardware-Beschreibungen im AUTOSAR-Standard. Bei der Modellierung von ECU-Ressourcenbeschreibungen müssen Peripheriemodule über die beiden spezialisierten HWPort-Klassen angebunden werden: prozessorzugängliche Register-/Speicherschnittstellen sind als <code>MemoryMappedHWPort</code> zu typisieren, während Verbindungen zur ECU-Elektronik als <code>PeripheralHWPort</code> abzubilden sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-af17db3d2b57ee43", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Spezifikation der Hardware-Ressourcen (AUTOSAR Resource Template ECU). Das Diagramm modelliert die strukturelle Anbindung und Schnittstellenverknüpfung von peripheren Hardware-Komponenten (<code>Peripheral</code>) an Prozessoren und ECU-Elektronik über Hardware-Ports im Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>HWElement</code></strong>: Allgemeine Hardware-Basisklasse, spezialisiert bzw. instanziiert durch:\n<ul class=\"fig-list\"><li><code>ProcessingUnit</code>: Repräsentiert die Recheneinheit/den Prozessorkern.\n</li><li><code>Peripheral</code>: Repräsentiert die periphere Hardware-Komponente.\n</li><li><code>ECUElectronics</code>: Repräsentiert die übergeordnete Steuergeräte-Elektronik.\n</li></ul>\n</li><li><strong><code>HWPort</code></strong>: Allgemeine Schnittstellen-Basisklasse für Hardware-Verbindungen, spezialisiert durch:\n<ul class=\"fig-list\"><li><code>MemoryMappedHWPort</code>: Speicherabgebildeter Port für den prozessornahen Zugriff.\n</li><li><code>PeripheralHWPort</code>: Hardware-Port zur peripheren Anbindung an die ECU-Elektronik.\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>ProcessingUnit</code> referenziert über eine gerichtete Abhängigkeit (gestrichelter Pfeil mit offener Pfeilspitze) den <code>MemoryMappedHWPort</code>.\n</li><li><code>Peripheral</code> referenziert über eine gerichtete Abhängigkeit nach links den <code>MemoryMappedHWPort</code>.\n</li><li><code>Peripheral</code> referenziert über eine gerichtete Abhängigkeit nach rechts den <code>PeripheralHWPort</code>.\n</li><li><code>ECUElectronics</code> referenziert über eine gerichtete Abhängigkeit von oben den <code>PeripheralHWPort</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die topologische Kopplung: Peripherieelemente koppeln prozessorintern über memory-mapped Hardware-Ports an die Recheneinheit und extern/steuergeräteseitig über Peripheral-Hardware-Ports an die Steuergeräteelektronik.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gilt als normative Metamodell-Definition für ECU-Hardware-Beschreibungen im AUTOSAR-Standard. Bei der Modellierung von ECU-Ressourcenbeschreibungen müssen Peripheriemodule über die beiden spezialisierten HWPort-Klassen angebunden werden: prozessorzugängliche Register-/Speicherschnittstellen sind als <code>MemoryMappedHWPort</code> zu typisieren, während Verbindungen zur ECU-Elektronik als <code>PeripheralHWPort</code> abzubilden sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d32029cc058a357f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Spezifikation der Hardware-Ressourcen (AUTOSAR Resource Template ECU). Das Diagramm modelliert die strukturelle Anbindung und Schnittstellenverknüpfung von peripheren Hardware-Komponenten (<code>Peripheral</code>) an Prozessoren und ECU-Elektronik über Hardware-Ports im Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>HWElement</code></strong>: Allgemeine Hardware-Basisklasse, spezialisiert bzw. instanziiert durch:\n<ul class=\"fig-list\"><li><code>ProcessingUnit</code>: Repräsentiert die Recheneinheit/den Prozessorkern.\n</li><li><code>Peripheral</code>: Repräsentiert die periphere Hardware-Komponente.\n</li><li><code>ECUElectronics</code>: Repräsentiert die übergeordnete Steuergeräte-Elektronik.\n</li></ul>\n</li><li><strong><code>HWPort</code></strong>: Allgemeine Schnittstellen-Basisklasse für Hardware-Verbindungen, spezialisiert durch:\n<ul class=\"fig-list\"><li><code>MemoryMappedHWPort</code>: Speicherabgebildeter Port für den prozessornahen Zugriff.\n</li><li><code>PeripheralHWPort</code>: Hardware-Port zur peripheren Anbindung an die ECU-Elektronik.\n</li></ul>\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li><code>ProcessingUnit</code> referenziert über eine gerichtete Abhängigkeit (gestrichelter Pfeil mit offener Pfeilspitze) den <code>MemoryMappedHWPort</code>.\n</li><li><code>Peripheral</code> referenziert über eine gerichtete Abhängigkeit nach links den <code>MemoryMappedHWPort</code>.\n</li><li><code>Peripheral</code> referenziert über eine gerichtete Abhängigkeit nach rechts den <code>PeripheralHWPort</code>.\n</li><li><code>ECUElectronics</code> referenziert über eine gerichtete Abhängigkeit von oben den <code>PeripheralHWPort</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die topologische Kopplung: Peripherieelemente koppeln prozessorintern über memory-mapped Hardware-Ports an die Recheneinheit und extern/steuergeräteseitig über Peripheral-Hardware-Ports an die Steuergeräteelektronik.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gilt als normative Metamodell-Definition für ECU-Hardware-Beschreibungen im AUTOSAR-Standard. Bei der Modellierung von ECU-Ressourcenbeschreibungen müssen Peripheriemodule über die beiden spezialisierten HWPort-Klassen angebunden werden: prozessorzugängliche Register-/Speicherschnittstellen sind als <code>MemoryMappedHWPort</code> zu typisieren, während Verbindungen zur ECU-Elektronik als <code>PeripheralHWPort</code> abzubilden sind.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a134c34c7d19f43f", "to": "FIG-ac9f9f220cf8234d", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ac9f9f220cf8234d", "to": "FIG-af17db3d2b57ee43", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-af17db3d2b57ee43", "to": "FIG-d32029cc058a357f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
